import{_ as t,o as r,c as a,ae as i}from"./chunks/framework.CK6jtcgr.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),o={name:"guide/architecture.md"};function n(l,e,s,c,d,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This page is the manual map for the public SocioProphet architecture.</p><p>SocioProphet is a governed operational intelligence system built for institutions, operators, learners, and builders. The public architecture is organized around bounded execution, deterministic safety claims, proof-bearing workflows, and explicit separation between public-safe documentation and restricted operational detail.</p><h2 id="_1-core-architectural-thesis" tabindex="-1">1. Core architectural thesis <a class="header-anchor" href="#_1-core-architectural-thesis" aria-label="Permalink to &quot;1. Core architectural thesis&quot;">​</a></h2><p>The platform is organized around a few core claims:</p><ul><li>intelligence must be governed</li><li>important transitions must be attributable</li><li>consequential actions must produce evidence</li><li>reversibility is a design property, not an afterthought</li><li>institutional deployment requires explicit safeguards and review boundaries</li><li>public documentation must explain the architecture honestly without disclosing restricted tactical internals</li></ul><p>This is not a chat-first architecture. It is a controlled systems architecture.</p><h2 id="_2-primary-layers" tabindex="-1">2. Primary layers <a class="header-anchor" href="#_2-primary-layers" aria-label="Permalink to &quot;2. Primary layers&quot;">​</a></h2><h3 id="organizations-and-institutional-deployment" tabindex="-1">Organizations and institutional deployment <a class="header-anchor" href="#organizations-and-institutional-deployment" aria-label="Permalink to &quot;Organizations and institutional deployment&quot;">​</a></h3><p>Organizations is the institutional umbrella surface. It is where public-sector, nonprofit, educational, sovereign, and mission-aligned deployments are framed.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/organizations-governance-and-institutional-safety/" target="_blank" rel="noreferrer">Organizations Governance and Institutional Safety</a></li><li><a href="https://socioprophet.com/documentation/platform-human-protection-and-safeguarding/" target="_blank" rel="noreferrer">Platform Human Protection and Safeguarding</a></li><li><a href="https://socioprophet.com/documentation/public-vs-restricted-security-boundary/" target="_blank" rel="noreferrer">Public vs Restricted Security Boundary</a></li></ul><h3 id="governed-ai-and-cybernetics" tabindex="-1">Governed AI and cybernetics <a class="header-anchor" href="#governed-ai-and-cybernetics" aria-label="Permalink to &quot;Governed AI and cybernetics&quot;">​</a></h3><p>This layer explains how bounded execution, human oversight, and proof-bearing control loops are organized.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/governed-ai-and-cybernetics/" target="_blank" rel="noreferrer">Governed AI and Cybernetics</a></li><li><a href="https://socioprophet.com/documentation/deterministic-ai-and-mathematical-safety/" target="_blank" rel="noreferrer">Deterministic AI and Mathematical Safety</a></li><li><a href="https://socioprophet.com/documentation/provenance-promotion-and-reversibility/" target="_blank" rel="noreferrer">Provenance, Promotion, and Reversibility</a></li></ul><h3 id="agent-plane-and-operator-workflows" tabindex="-1">Agent plane and operator workflows <a class="header-anchor" href="#agent-plane-and-operator-workflows" aria-label="Permalink to &quot;Agent plane and operator workflows&quot;">​</a></h3><p>This layer describes operator roles, workflow states, capability routing, review, and bounded execution.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/agent-plane-and-operator-workflows/" target="_blank" rel="noreferrer">Agent Plane and Operator Workflows</a></li><li><a href="https://socioprophet.com/documentation/auth-and-connections/" target="_blank" rel="noreferrer">Auth and Connections</a></li><li><a href="https://socioprophet.com/documentation/provider-capability-routing/" target="_blank" rel="noreferrer">Provider Capability Routing</a></li><li><a href="https://socioprophet.com/documentation/provider-safety-and-capability-eligibility/" target="_blank" rel="noreferrer">Provider Safety and Capability Eligibility</a></li><li><a href="https://socioprophet.com/documentation/auth-recovery-and-connection-health/" target="_blank" rel="noreferrer">Auth Recovery and Connection Health</a></li></ul><h3 id="entity-analytics" tabindex="-1">Entity Analytics <a class="header-anchor" href="#entity-analytics" aria-label="Permalink to &quot;Entity Analytics&quot;">​</a></h3><p>Entity Analytics is the governed identity, event, graph, merge, and proof subsystem.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/entity-analytics-reference/" target="_blank" rel="noreferrer">Entity Analytics Reference</a></li><li><a href="https://socioprophet.com/documentation/worked-example-michael-cross-context/" target="_blank" rel="noreferrer">Worked Example: Michael Cross-Context</a></li><li><a href="https://socioprophet.com/documentation/entity-analytics-overview/" target="_blank" rel="noreferrer">Entity Analytics Overview</a></li><li><a href="https://socioprophet.com/documentation/identity-prime-and-event-ir/" target="_blank" rel="noreferrer">Identity Prime and Event-IR</a></li><li><a href="https://socioprophet.com/documentation/entity-graph-and-safe-linkage/" target="_blank" rel="noreferrer">Entity Graph and Safe Linkage</a></li><li><a href="https://socioprophet.com/documentation/policy-constrained-merging-and-unmerge/" target="_blank" rel="noreferrer">Policy-Constrained Merging and Unmerge</a></li><li><a href="https://socioprophet.com/documentation/marketer-safe-outputs-and-segment-proofs/" target="_blank" rel="noreferrer">Marketer-Safe Outputs and Segment Proofs</a></li></ul><h3 id="authorized-cyberdefense-and-simulation" tabindex="-1">Authorized cyberdefense and simulation <a class="header-anchor" href="#authorized-cyberdefense-and-simulation" aria-label="Permalink to &quot;Authorized cyberdefense and simulation&quot;">​</a></h3><p>This layer is public-safe and defense-first. It covers defensive validation, simulation boundaries, evidence, and institutional review posture.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/authorized-cyberdefense-and-simulation/" target="_blank" rel="noreferrer">Authorized Cyberdefense and Simulation</a></li><li><a href="https://socioprophet.com/documentation/boundary-centric-cyber-hypergraph/" target="_blank" rel="noreferrer">Boundary-Centric Cyber Hypergraph</a></li><li><a href="https://socioprophet.com/documentation/public-vs-restricted-security-boundary/" target="_blank" rel="noreferrer">Public vs Restricted Security Boundary</a></li></ul><h2 id="_3-learning-and-theory-layer" tabindex="-1">3. Learning and theory layer <a class="header-anchor" href="#_3-learning-and-theory-layer" aria-label="Permalink to &quot;3. Learning and theory layer&quot;">​</a></h2><p>SocioProphet also includes a learning, theory, and semantic-model layer. This is where the system’s representational logic, topic organization, and curriculum-facing structure are documented.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/operating-modes-learning-and-defense/" target="_blank" rel="noreferrer">Operating Modes: Learning and Defense</a></li><li><a href="https://socioprophet.com/documentation/twenty-three-topic-canon/" target="_blank" rel="noreferrer">23-Topic Canon</a></li><li><a href="https://socioprophet.com/documentation/governed-cybernetic-stack/" target="_blank" rel="noreferrer">Governed Cybernetic Stack</a></li><li><a href="https://socioprophet.com/documentation/semantic-vector-stack/" target="_blank" rel="noreferrer">Semantic Vector Stack</a></li><li><a href="https://socioprophet.com/documentation/semantic-representation-ladder/" target="_blank" rel="noreferrer">Semantic Representation Ladder</a></li><li><a href="https://socioprophet.com/documentation/lsa-lsi-lda-geometry/" target="_blank" rel="noreferrer">LSA / LSI / LDA Geometry</a></li><li><a href="https://socioprophet.com/documentation/semantic-model-workstreams/" target="_blank" rel="noreferrer">Semantic Model Workstreams</a></li><li><a href="https://socioprophet.com/documentation/hybrid-representation-builder/" target="_blank" rel="noreferrer">Hybrid Representation Builder</a></li><li><a href="https://socioprophet.com/documentation/temporal-graph-evolution/" target="_blank" rel="noreferrer">Temporal Graph Evolution</a></li></ul><h2 id="_4-product-and-surface-layer" tabindex="-1">4. Product and surface layer <a class="header-anchor" href="#_4-product-and-surface-layer" aria-label="Permalink to &quot;4. Product and surface layer&quot;">​</a></h2><p>The public site exposes multiple surfaces, but they are not all equivalent. Some are institutional, some are learning-oriented, and some are domain or product extensions.</p><p>Key references:</p><ul><li><a href="https://socioprophet.com/documentation/products/overview/" target="_blank" rel="noreferrer">Products Overview</a></li><li><a href="https://socioprophet.com/documentation/product-surface-standard/" target="_blank" rel="noreferrer">Product Surface Standard</a></li><li><a href="https://socioprophet.com/documentation/product-surface-maturity-matrix/" target="_blank" rel="noreferrer">Product Surface Maturity Matrix</a></li><li><a href="https://socioprophet.com/documentation/domain-surface/" target="_blank" rel="noreferrer">Domain Surface</a></li><li><a href="https://socioprophet.com/documentation/digital-trust-and-capability-routing/" target="_blank" rel="noreferrer">Digital Trust and Capability Routing</a></li><li><a href="https://socioprophet.com/documentation/academy-policy-index/" target="_blank" rel="noreferrer">Academy Policy Index</a></li></ul><h2 id="_5-boundary-first-model" tabindex="-1">5. Boundary-first model <a class="header-anchor" href="#_5-boundary-first-model" aria-label="Permalink to &quot;5. Boundary-first model&quot;">​</a></h2><p>One of the key public-safe architectural ideas is that the boundary is the unit of truth.</p><p>The system models crossings through explicit structures such as:</p><ul><li>component</li><li>port</li><li>contract</li><li>boundary event</li><li>evidence</li><li>expectation</li><li>finding</li><li>artifact</li></ul><p>This keeps the architecture explainable at the point where action, policy, and observation meet.</p><p>Primary reference:</p><ul><li><a href="https://socioprophet.com/documentation/boundary-centric-cyber-hypergraph/" target="_blank" rel="noreferrer">Boundary-Centric Cyber Hypergraph</a></li></ul><h2 id="_6-deterministic-and-bounded-posture" tabindex="-1">6. Deterministic and bounded posture <a class="header-anchor" href="#_6-deterministic-and-bounded-posture" aria-label="Permalink to &quot;6. Deterministic and bounded posture&quot;">​</a></h2><p>SocioProphet presents itself publicly as deterministic AI because it is built around bounded execution, measurable safety, and proof-bearing transitions rather than ambient improvisation.</p><p>Primary references:</p><ul><li><a href="https://socioprophet.com/documentation/deterministic-ai-and-mathematical-safety/" target="_blank" rel="noreferrer">Deterministic AI and Mathematical Safety</a></li><li><a href="https://socioprophet.com/documentation/governed-ai-and-cybernetics/" target="_blank" rel="noreferrer">Governed AI and Cybernetics</a></li><li><a href="https://socioprophet.com/documentation/provenance-promotion-and-reversibility/" target="_blank" rel="noreferrer">Provenance, Promotion, and Reversibility</a></li></ul><h2 id="_7-public-safe-versus-restricted-material" tabindex="-1">7. Public-safe versus restricted material <a class="header-anchor" href="#_7-public-safe-versus-restricted-material" aria-label="Permalink to &quot;7. Public-safe versus restricted material&quot;">​</a></h2><p>The public docs explain the architecture, the control model, the safety posture, the governance boundary, and the evidence model.</p><p>The public docs do not contain restricted tactical internals such as:</p><ul><li>sensitive operator kits</li><li>high-fidelity adversary simulation mechanics</li><li>exact detection thresholds</li><li>exploit or persistence workflows</li><li>privileged runbooks</li><li>misuse-enabling tradecraft</li></ul><p>Primary reference:</p><ul><li><a href="https://socioprophet.com/documentation/public-vs-restricted-security-boundary/" target="_blank" rel="noreferrer">Public vs Restricted Security Boundary</a></li></ul><h2 id="_8-reading-paths" tabindex="-1">8. Reading paths <a class="header-anchor" href="#_8-reading-paths" aria-label="Permalink to &quot;8. Reading paths&quot;">​</a></h2><h3 id="executive-and-institutional-path" tabindex="-1">Executive and institutional path <a class="header-anchor" href="#executive-and-institutional-path" aria-label="Permalink to &quot;Executive and institutional path&quot;">​</a></h3><ul><li><a href="https://socioprophet.com/documentation/getting-started/" target="_blank" rel="noreferrer">Getting Started</a></li><li><a href="https://socioprophet.com/documentation/organizations-governance-and-institutional-safety/" target="_blank" rel="noreferrer">Organizations Governance and Institutional Safety</a></li><li><a href="https://socioprophet.com/documentation/deterministic-ai-and-mathematical-safety/" target="_blank" rel="noreferrer">Deterministic AI and Mathematical Safety</a></li><li><a href="https://socioprophet.com/documentation/authorized-cyberdefense-and-simulation/" target="_blank" rel="noreferrer">Authorized Cyberdefense and Simulation</a></li></ul><h3 id="operator-and-security-path" tabindex="-1">Operator and security path <a class="header-anchor" href="#operator-and-security-path" aria-label="Permalink to &quot;Operator and security path&quot;">​</a></h3><ul><li><a href="https://socioprophet.com/documentation/governed-ai-and-cybernetics/" target="_blank" rel="noreferrer">Governed AI and Cybernetics</a></li><li><a href="https://socioprophet.com/documentation/agent-plane-and-operator-workflows/" target="_blank" rel="noreferrer">Agent Plane and Operator Workflows</a></li><li><a href="https://socioprophet.com/documentation/boundary-centric-cyber-hypergraph/" target="_blank" rel="noreferrer">Boundary-Centric Cyber Hypergraph</a></li><li><a href="https://socioprophet.com/documentation/entity-analytics-reference/" target="_blank" rel="noreferrer">Entity Analytics Reference</a></li></ul><h3 id="builder-and-researcher-path" tabindex="-1">Builder and researcher path <a class="header-anchor" href="#builder-and-researcher-path" aria-label="Permalink to &quot;Builder and researcher path&quot;">​</a></h3><ul><li><a href="https://socioprophet.com/documentation/semantic-vector-stack/" target="_blank" rel="noreferrer">Semantic Vector Stack</a></li><li><a href="https://socioprophet.com/documentation/hybrid-representation-builder/" target="_blank" rel="noreferrer">Hybrid Representation Builder</a></li><li><a href="https://socioprophet.com/documentation/operating-modes-learning-and-defense/" target="_blank" rel="noreferrer">Operating Modes: Learning and Defense</a></li><li><a href="https://socioprophet.com/documentation/twenty-three-topic-canon/" target="_blank" rel="noreferrer">23-Topic Canon</a></li></ul><h2 id="_9-use-this-page" tabindex="-1">9. Use this page <a class="header-anchor" href="#_9-use-this-page" aria-label="Permalink to &quot;9. Use this page&quot;">​</a></h2><p>Use this page as the architecture map.</p><p>Use the sidebar to move into the layer that matches the question at hand:</p><ul><li>institutional deployment</li><li>governed execution</li><li>agent operations</li><li>analytics and evidence</li><li>defense and validation</li><li>learning and theory</li><li>product surfaces</li></ul>',64)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
